function createSmokeTestSecretProvider({
  providerId = "smoke-secret-provider-reference",
  kind = "test_secret_provider",
  status = "resolved",
  value = "fake-task-0300-secret-value",
  expiresAt = "2026-08-08T01:15:00.000Z",
  scope,
  throwError = false,
} = {}) {
  const calls = [];

  return {
    calls,
    provider: {
      identity: {
        providerId,
        kind,
        authority: "system",
        implementationVersion: "smoke-test-secret-provider-v1",
        configurationVersion: "smoke-test-secret-provider-config-v1",
      },
      resolve(request) {
        calls.push(JSON.parse(JSON.stringify(request)));

        if (throwError) {
          throw new Error("test secret provider failed\n    at smoke-secret:1:1");
        }

        if (status === "missing") {
          return {
            status: "missing",
            code: "smoke_test_secret_missing",
            message: "missing fake credential",
          };
        }

        if (status === "denied") {
          return {
            status: "denied",
            code: "smoke_test_secret_denied",
            message: "denied fake credential",
          };
        }

        if (status === "error") {
          return {
            status: "error",
            code: "smoke_test_secret_error",
            message: "sanitized fake provider error",
          };
        }

        return {
          status: "resolved",
          kind: "bearer_token",
          value,
          expiresAt,
          scope: scope ?? request.credentialScope,
          resolutionReference: "smoke-resolution-reference",
        };
      },
    },
  };
}

async function withTemporaryEnvironmentValue(name, value, callback) {
  const previous = process.env[name];

  process.env[name] = value;

  try {
    return await callback();
  } finally {
    if (previous === undefined) {
      delete process.env[name];
    } else {
      process.env[name] = previous;
    }
  }
}

async function withTemporarilyUnsetEnvironmentValue(name, callback) {
  const previous = process.env[name];

  delete process.env[name];

  try {
    return await callback();
  } finally {
    if (previous !== undefined) {
      process.env[name] = previous;
    }
  }
}

